// =============================================================================
// KS-1151 — POST /api/auth/refresh must REFUSE an OAuth-minted refresh token.
// =============================================================================
//
// The interactive refresh route (routes/auth.ts, `authRoutes.post('/refresh')`)
// accepted ANY valid refresh token from ANY party with no client credential and
// re-minted a login-shape pair: `generateTokenPair(user, session.id)` with no
// third argument — no `client_id`, no `authMethod`, scopes = the role default.
// So a third-party app holding a NARROW OAuth refresh token (`openid`) obtained
// the user's FULL role authority in one unauthenticated call, and the OAuth
// grant's client binding (KS-823) and granted-scope label (KS-835) were shed one
// route over ("the launder"). Worse, the route rotated + denylisted the
// presented jti, so the laundering CONSUMED the bound token: the legitimate
// client's next OAuth refresh read 'Refresh token revoked'.
//
// The fix (the fail-closed mirror of the OAuth grant's binding refusal): a token
// carrying `client_id` OR `authMethod: 'oauth'` is refused at this route with
// 401, BEFORE the session lookup, so it is neither rotated nor denylisted.
//
// WHAT THIS FILE PROVES (every cell over a raw socket, with the REAL jwt.ts —
// the tokens are minted in-process by `generateTokenPair` against the setup
// file's RS256 keypair and verified by the real `verifyRefreshToken`; only
// persistence is mocked):
//   1. H-LAUNDER (body)   — an OAuth-minted refresh token → 401; NOT rotated,
//                           NOT denylisted; no token issued.  RED before the fix
//                           (200 + a login-shape pair; the session rotated).
//   2. H-LAUNDER (cookie) — the same token in the `refresh_token` cookie, no
//                           body → 401.                        RED before the fix.
//   3. the `client_id`-only arm — a token carrying `client_id` and NO label
//      (the shape minted between the binding and the label landing): the
//      minted OAuth token decoded, `authMethod` removed, re-signed with the
//      same key → 401. Makes the arm on `authMethod` alone insufficient.
//                                                              RED before the fix.
//   4. CONTROL — a login-minted pair (no third argument) still refreshes → 200,
//      the re-minted access token carries no `client_id` / `authMethod`, and
//      the session IS rotated (the interactive flow is unchanged).
//                                                              GREEN both sides.
//   5. CONTROL — garbage → 401 (the harness discriminates).    GREEN both sides.
//
// The listener binds 127.0.0.1 (the ks860 loopback guard walks services/).
// =============================================================================

import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
import express from 'express';
import cookieParser from 'cookie-parser';
import net from 'node:net';
import jwt from 'jsonwebtoken';
import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';

const silent = { debug: vi.fn(), info: vi.fn(), warn: vi.fn(), error: vi.fn(), log: vi.fn() };
vi.mock('../utils/logger', () => ({ logger: silent, createLogger: () => silent, validateEnv: vi.fn() }));
vi.mock('@secuura/shared/utils/logger', () => ({ logger: silent, createLogger: () => silent }));

const USER = {
  id: 'user-1151', email: 'u1151@secuura.local', status: 'ACTIVE', role: 'OWNER',
  verificationLevel: 'BASIC', mfaEnabled: false, tenantId: 'ten-1', organizationId: 'org-1',
};

/** The persistence the route touches, recorded so the cells can assert what was NOT done. */
