vi.mock('../events', () => ({ publishEvent: vi.fn(async () => undefined), EventTypes: {} }));

let server: Server;
let port: number;
let mint: (user: unknown, sessionId: string, opts?: { clientId: string; scopes: readonly string[] }) => { accessToken: string; refreshToken: string };

beforeAll(async () => {
  const jwtMod = await import('../services/jwt');
  await jwtMod.initJwtKeys();
  mint = jwtMod.generateTokenPair as unknown as typeof mint;
  const { authRoutes } = await import('../routes/auth');
  const { errorHandler } = await import('../middleware/errorHandler');
  const app = express();
  app.use(cookieParser()); // as index.ts mounts it — the route reads the refresh_token cookie
  app.use(express.json({ limit: '10mb' }));
  app.use(express.urlencoded({ extended: true }));
  app.use('/api/auth', authRoutes);
  app.use(errorHandler);
  server = app.listen(0, '127.0.0.1');
  await new Promise<void>((r) => server.once('listening', () => r()));
  port = (server.address() as AddressInfo).port;
});
afterAll(async () => { await new Promise<void>((r) => server.close(() => r())); });

type Reply = { status: number; body: string; json: Record<string, unknown> | null; setCookie: string[] };

/** A real socket, real bytes. */
function raw(method: string, path: string, body: unknown, headers: Record<string, string> = {}): Promise<Reply> {
  return new Promise((resolve, reject) => {
    const payload = body === undefined ? '' : JSON.stringify(body);
    const lines = [
      `${method} ${path} HTTP/1.1`, 'Host: 127.0.0.1', 'Connection: close',
      ...(payload ? ['Content-Type: application/json', `Content-Length: ${Buffer.byteLength(payload)}`] : []),
      ...Object.entries(headers).map(([k, v]) => `${k}: ${v}`), '', '',
    ].join('\r\n');
    const sock = net.connect(port, '127.0.0.1', () => sock.write(lines + payload));
    const chunks: Buffer[] = [];
    sock.on('data', (d: Buffer) => chunks.push(d));
    sock.on('error', reject);
    sock.on('end', () => {
      const text = Buffer.concat(chunks).toString('utf8');
      const status = Number(text.slice(9, 12));
      const head = text.slice(0, text.indexOf('\r\n\r\n'));
      const setCookie = head.split('\r\n').filter((l) => /^set-cookie:/i.test(l)).map((l) => l.slice(11).trim());
      const bodyText = text.slice(text.indexOf('\r\n\r\n') + 4);
      let json: Record<string, unknown> | null = null;
      try { json = JSON.parse(bodyText.replace(/^[0-9a-f]+\r\n/i, '').trim()); } catch { /* not json */ }
      resolve({ status, body: bodyText, json, setCookie });
    });
  });
}

const claims = (tok: unknown) => (jwt.decode(String(tok)) as Record<string, unknown> | null) ?? {};
const refreshBody = (token: string) => raw('POST', '/api/auth/refresh', { refreshToken: token });
const refreshCookie = (token: string) => raw('POST', '/api/auth/refresh', undefined, { Cookie: `refresh_token=${encodeURIComponent(token)}` });
const issuedNothing = (r: Reply) => {
  const data = (r.json?.data as Record<string, unknown> | undefined) ?? {};
  return typeof data.accessToken !== 'string' && !r.setCookie.some((c) => c.startsWith('refresh_token='));
};

/**
 * The #983-era shape: `client_id` bound, no `authMethod` label. Built from a real
 * OAuth mint by dropping the label and re-signing RS256 with the same key the
 * setup file provisioned (the route verifies by public key + algorithm, so the
 * product's own `verifyRefreshToken` accepts it as genuine).
 */
function clientIdOnlyToken(): string {
  const { refreshToken } = mint(USER, 'sess-x', { clientId: 'client-1', scopes: ['openid'] });
  const { authMethod: _label, iat: _iat, exp: _exp, ...rest } = claims(refreshToken) as Record<string, unknown>;
  expect(_label, 'the fixture starts from a labelled OAuth mint').toBe('oauth');
  expect(rest.client_id).toBe('client-1');
  const privatePem = Buffer.from(String(process.env.JWT_PRIVATE_KEY), 'base64').toString('utf8');
  return jwt.sign(rest, privatePem, { algorithm: 'RS256', expiresIn: 600, ...(process.env.JWT_KEY_ID ? { keyid: process.env.JWT_KEY_ID } : {}) });
}

beforeEach(() => { world.rotated = []; world.denylisted = []; world.sessionLookups = []; vi.clearAllMocks(); });

describe('KS-1151 — POST /api/auth/refresh refuses an OAuth-minted refresh token (fail-closed, before any side effect)', () => {
  it('1. H-LAUNDER — an OAuth-minted refresh token in the body → 401, no token issued, the session NOT rotated, the jti NOT denylisted', async () => {
    const { refreshToken } = mint(USER, 'sess-x', { clientId: 'client-1', scopes: ['openid'] });
    expect(claims(refreshToken).client_id, 'the fixture IS bound').toBe('client-1');
    expect(claims(refreshToken).authMethod, 'the fixture IS labelled').toBe('oauth');
    const r = await refreshBody(refreshToken);
    expect(r.status, `body: ${r.body.slice(0, 200)}`).toBe(401);
    expect(r.json?.success).toBe(false);
    expect(issuedNothing(r), 'no access token and no refresh cookie').toBe(true);
    expect(world.rotated, 'the presented token must not be consumed by rotation').toEqual([]);
    expect(world.denylisted, 'the presented jti must not be denylisted').toEqual([]);
  });

  it('2. H-LAUNDER-COOKIE — the same token in the refresh_token cookie, no body → 401, nothing rotated or denylisted', async () => {
    const { refreshToken } = mint(USER, 'sess-x', { clientId: 'client-1', scopes: ['openid'] });
    const r = await refreshCookie(refreshToken);
    expect(r.status, `body: ${r.body.slice(0, 200)}`).toBe(401);
    expect(issuedNothing(r)).toBe(true);
    expect(world.rotated).toEqual([]);
    expect(world.denylisted).toEqual([]);
  });

  it('3. the client_id-only arm — a bound token with NO authMethod label → 401 (the label arm alone would let it through)', async () => {
    const token = clientIdOnlyToken();
    expect(claims(token).authMethod).toBeUndefined();
    expect(claims(token).client_id).toBe('client-1');
    const r = await refreshBody(token);
    expect(r.status, `body: ${r.body.slice(0, 200)}`).toBe(401);
    expect(issuedNothing(r)).toBe(true);
    expect(world.rotated).toEqual([]);
    expect(world.denylisted).toEqual([]);
  });

  it('4. CONTROL — a login-minted pair (no third argument) still refreshes → 200, unbound access token, the session rotated', async () => {
    const { refreshToken } = mint(USER, 'sess-x');
    expect(claims(refreshToken).client_id).toBeUndefined();
    expect(claims(refreshToken).authMethod).toBeUndefined();
    const r = await refreshBody(refreshToken);
    expect(r.status, `body: ${r.body.slice(0, 200)}`).toBe(200);
    const data = (r.json?.data as Record<string, unknown> | undefined) ?? {};
    expect(typeof data.accessToken).toBe('string');
    expect(claims(data.accessToken).client_id).toBeUndefined();
    expect(claims(data.accessToken).authMethod).toBeUndefined();
    expect(r.setCookie.some((c) => c.startsWith('refresh_token='))).toBe(true);
    expect(world.rotated).toEqual(['sess-x']); // the interactive flow's own rotation, unchanged
    expect(world.denylisted).toHaveLength(1);
  });

  it('5. CONTROL — garbage → 401 (the route verifies; the harness discriminates)', async () => {
    const r = await refreshBody('not-a-token');
    expect(r.status).toBe(401);
    expect(world.rotated).toEqual([]);
  });
});
